package interfaces

import (
	"context"
	"io"
)

// DataType identifies the columnar physical type.
type DataType uint8

const (
	TypeInt64 DataType = iota
	TypeFloat64
	TypeDecimal
	TypeVarChar
	TypeDate
	TypeBool
)

// ColumnVector represents a single column chunk with null bitmask.
type ColumnVector struct {
	Type     DataType
	Int64s   []int64
	Float64s []float64
	Strings  []string
	Bools    []bool
	NullMask []bool // true indicates NULL
	Length   int
}

// RecordBatch groups column vectors of the same length.
type RecordBatch struct {
	Columns []ColumnVector
	Length  int
}

// EngineError represents a domain error with a stable machine-readable code.
type EngineError struct {
	Code    string
	Message string
}

func (e *EngineError) Error() string { return e.Message }

const (
	ErrSyntaxError          = "syntax_error"
	ErrUnsupportedStatement = "unsupported_statement"
	ErrTypeMismatch         = "type_mismatch"
	ErrTableNotFound        = "table_not_found"
	ErrColumnNotFound       = "column_not_found"
	ErrLimitExceeded        = "limit_exceeded"
	ErrDivisionByZero       = "division_by_zero"
	ErrQueryTooLarge        = "query_too_large"
	ErrDepthExceeded        = "depth_exceeded"
)

// TableMetadata contains schema and statistics for a registered table.
type TableMetadata struct {
	Name        string
	ColumnNames []string
	Schema      []DataType
	RowCount    int64
	ByteSize    int64
}

// BatchReader iterates over record batches.
type BatchReader interface {
	Next(ctx context.Context) (*RecordBatch, error)
	Schema() []DataType
	ColumnNames() []string
	Close() error
}

// TableCatalog manages registered CSV tables and creates batch scanners.
type TableCatalog interface {
	RegisterCSV(name string, r io.Reader, schema []DataType, maxScanBytes int64, batchSize int) error
	GetTable(name string) (*TableMetadata, error)
	ScanTable(ctx context.Context, name string, projections []string, batchSize int) (BatchReader, error)
	ListTables() []string
	Close() error
}

package interfaces

// BinaryOp represents a binary operator token in an expression.
type BinaryOp int

const (
	OpEq BinaryOp = iota
	OpNotEq
	OpLt
	OpLtEq
	OpGt
	OpGtEq
	OpAdd
	OpSub
	OpMul
	OpDiv
	OpAnd
	OpOr
	OpLike
)

// Expr represents an AST expression node.
type Expr interface {
	isExpr()
}

// ColumnRef references a column name with optional table qualification.
type ColumnRef struct {
	Table string
	Name  string
}

func (ColumnRef) isExpr() {}

// LiteralExpr represents a typed scalar constant or NULL.
type LiteralExpr struct {
	Type   DataType
	Value  any
	IsNull bool
}

func (LiteralExpr) isExpr() {}

// BinaryExpr represents binary operations (arithmetic, comparison, logical).
type BinaryExpr struct {
	Op    BinaryOp
	Left  Expr
	Right Expr
}

func (BinaryExpr) isExpr() {}

// UnaryExpr represents unary operations (NOT, IS NULL, IS NOT NULL).
type UnaryExpr struct {
	Op      string
	Operand Expr
}

func (UnaryExpr) isExpr() {}

// CaseWhen represents a single WHEN ... THEN ... arm in a CASE expression.
type CaseWhen struct {
	When Expr
	Then Expr
}

// CaseExpr represents CASE [expr] WHEN ... THEN ... ELSE ... END.
type CaseExpr struct {
	Operand Expr
	Whens   []CaseWhen
	Else    Expr
}

func (CaseExpr) isExpr() {}

// CastExpr represents CAST(expr AS type).
type CastExpr struct {
	Expr       Expr
	TargetType DataType
}

func (CastExpr) isExpr() {}

// AggregateCall represents an aggregate invocation (e.g. COUNT, SUM, AVG, MIN, MAX).
type AggregateCall struct {
	Func     string
	Distinct bool
	Args     []Expr
}

func (AggregateCall) isExpr() {}

// JoinType specifies the join semantics.
type JoinType int

const (
	JoinInner JoinType = iota
	JoinLeft
)

// JoinClause represents a JOIN relation with an ON condition.
type JoinClause struct {
	Type      JoinType
	Table     string
	Alias     string
	Condition Expr
}

// OrderByItem specifies an ORDER BY expression with ordering directions.
type OrderByItem struct {
	Expr       Expr
	Ascending  bool
	NullsFirst bool
}

// SelectItem represents a projected column or expression with an optional alias.
type SelectItem struct {
	Expr  Expr
	Alias string
}

// SelectStatement represents the AST for a parsed SELECT query.
type SelectStatement struct {
	Projections []SelectItem
	FromTable   string
	FromAlias   string
	Joins       []JoinClause
	Where       Expr
	GroupBy     []Expr
	Having      Expr
	OrderBy     []OrderByItem
	Limit       *int64
	Offset      *int64
}

// SQLParser parses SQL text into AST statements.
type SQLParser interface {
	Parse(sql string) (*SelectStatement, error)
}

package interfaces

import "context"

// Operator represents a physical vectorized execution operator.
type Operator interface {
	Init(ctx context.Context) error
	Next(ctx context.Context) (*RecordBatch, error)
	Schema() []DataType
	ColumnNames() []string
	Close() error
}

// ExecutionContext provides resource tracking and cancellation.
type ExecutionContext interface {
	Context() context.Context
	BatchSize() int
	MaxMemory() int64
}

// VectorEvaluator evaluates expressions over RecordBatches.
type VectorEvaluator interface {
	Evaluate(ctx context.Context, expr Expr, batch *RecordBatch, columnNames []string) (*ColumnVector, error)
}

// ExecutionEngine creates executable operator pipelines from physical plans.
type ExecutionEngine interface {
	Execute(ctx context.Context, plan PhysicalPlanNode) (Operator, error)
	Evaluator() VectorEvaluator
}

package interfaces

import (
	"context"
	"time"
)

// PhysicalPlanNode represents an operator node in the physical execution tree.
type PhysicalPlanNode interface {
	Name() string
	Children() []PhysicalPlanNode
	Schema() []DataType
	ColumnNames() []string
	Explain(analyze bool) string
}

// OperatorMetrics records runtime metrics for EXPLAIN ANALYZE.
type OperatorMetrics struct {
	OperatorName string
	RowsEmitted  int64
	BatchesCount int64
	Duration     time.Duration
}

// QueryPlanner transforms AST statements into optimized physical plans.
type QueryPlanner interface {
	Plan(ctx context.Context, stmt *SelectStatement, catalog TableCatalog) (PhysicalPlanNode, error)
	Explain(plan PhysicalPlanNode, analyze bool, metrics []OperatorMetrics) string
}

// RuleOptimizer applies rule-based optimizations (pushdowns, folding).
type RuleOptimizer interface {
	Optimize(plan PhysicalPlanNode) (PhysicalPlanNode, error)
}

package interfaces

import (
	"context"
	"io"
)

// Options configure the engine limits and defaults.
type Options struct {
	MaxScanBytes int64 // default: 104857600 (100MB)
	BatchSize    int   // default: 1024
	MaxMemory    int64 // default: 268435456 (256MB)
}

// RowsCursor provides iteration over query results.
type RowsCursor interface {
	Next() bool
	Scan(dest ...any) error
	Close() error
	CurrentBatch() *RecordBatch
}

// EngineAPI defines the full public SQL engine interface.
type EngineAPI interface {
	Close() error
	RegisterCSV(name string, r io.Reader, schema []DataType) error
	Query(ctx context.Context, sql string) (RowsCursor, error)
	Explain(ctx context.Context, sql string, analyze bool) (string, error)
}
